from pathlib import Path
p=Path('/app/image.ppm')
with p.open('r') as f:
    magic=f.readline().strip();
    assert magic=='P3'
    # read tokens generator
    def tokens():
        for line in f:
            if line.startswith('#'):
                continue
            for tok in line.split():
                yield tok
    it=tokens()
    w=int(next(it)); h=int(next(it)); maxv=int(next(it))
    print('w h max',w,h,maxv)
    # sample a grid 6x4
    sx=6; sy=4
    coords=[(int(x*(w-1)/(sx-1)), int(y*(h-1)/(sy-1))) for y in range(sy) for x in range(sx)]
    # We'll read through and capture these
    coords_set=set(coords)
    samples={}
    idx=0
    x=y=0
    for tok in it:
        v=int(tok)
        channel=idx%3
        pix_idx=idx//3
        y=pix_idx//w
        x=pix_idx%w
        if (x,y) in coords_set:
            if (x,y) not in samples:
                samples[(x,y)]=[0,0,0]
            samples[(x,y)][channel]=v
        idx+=1
        if idx>=w*h*3:
            break
    print('samples')
    for y in range(sy):
        for x in range(sx):
            print(samples[(int(x*(w-1)/(sx-1)), int(y*(h-1)/(sy-1)))], end=' ')
        print()
PY"}

